    for (let y = 2; y < 16; y += 4) { px(ctx, 0, y, 16, 2, '#543a26'); px(ctx, 0, y + 2, 16, 1, '#39281a'); }
    for (let i = 0; i < 8; i++) px(ctx, Math.floor(r() * 16), Math.floor(r() * 16), 1, 1, '#6b4a31');
