export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.musicOn = true;
    this.started = false;
    this.trackName = null;
    this.timer = null;
    this.master = null;
    this.musicBus = null;
    this.sfxBus = null;
    this.delay = null;
    this.step = 0;
    this.nextTime = 0;
    try {
      const s = JSON.parse(localStorage.getItem('starfall_audio') || '{}');
      if (s.music === false) this.musicOn = false;
      this.volume = s.volume ?? 0.6;
