  box(legL, .24, .1, .3, colorMat('#3b2a37'), 0, -.52, .03);
  const legR = new THREE.Group(); legR.position.set(0.15, 0.62, 0);
  box(legR, .22, .5, .26, legGeoMat, 0, -.25, 0);
